css:
body[data-theme="minimal"] { font-family: 'Inter', ui-sans-serif, system-ui, sans-serif; }
body[data-theme="minimal"] .display { font-family: 'Inter', ui-sans-serif, sans-serif; font-weight: 700; letter-spacing: -0.035em; }
body[data-theme="minimal"] .num-marker { font-variant-numeric: tabular-nums; }
/* neutral palette swap (slate → neutral) */
body[data-theme="minimal"] .text-slate-900 { color: #0a0a0a !important; }
body[data-theme="minimal"] .text-slate-700 { color: #404040 !important; }
body[data-theme="minimal"] .text-slate-600 { color: #525252 !important; }
body[data-theme="minimal"] .text-slate-500 { color: #737373 !important; }
body[data-theme="minimal"] .text-slate-400 { color: #a3a3a3 !important; }
body[data-theme="minimal"] .text-slate-300 { color: #d4d4d4 !important; }
body[data-theme="minimal"] .border-slate-200 { border-color: #e5e5e5 !important; }
body[data-theme="minimal"] .bg-slate-50 { background: #fafafa !important; }
body[data-theme="minimal"] .rule { background: linear-gradient(to right, transparent, #f5f5f5, transparent) !important; }
/* eyebrows: drop the uppercase + wide tracking for a quieter sentence-case look */
body[data-theme="minimal"] .uppercase.tracking-\[0\.2em\] { text-transform: none; letter-spacing: 0; font-weight: 500; font-size: 0.8125rem; }
body[data-theme="minimal"] .uppercase.tracking-wider { text-transform: none; letter-spacing: 0; }
